<script setup lang="ts">
import {computed, nextTick, onMounted, onUnmounted, ref, watch} from 'vue'
import {LayoutDashboard, UsersRound, ListTodo, Package, Building2, Gem, ScrollText, Settings2, ArrowUpRight, Plus, RefreshCw, Moon, Sun, ChevronRight, ArrowRight, CircleHelp, ShieldCheck, LockKeyhole, LogOut, X, Search, Check, Pause, Download, Monitor, Menu, CheckCheck, ArrowDownWideNarrow, AlertTriangle, Link2, Clock3, WifiOff} from 'lucide-vue-next'
import AccountCard from './components/AccountCard.vue'
import StatusPill from './components/StatusPill.vue'
import SystemGraph from './components/SystemGraph.vue'
import {makeDemo} from './demo'
import {request, setCSRF} from './api'
import type {Account, Overview, InventoryItem, Policy, Agent} from './types'

type Page = 'overview' | 'accounts' | 'plans' | 'inventory' | 'infrastructure' | 'orundum' | 'logs' | 'settings'
const nav = [
  {id: 'overview', label: '总览', en: 'OVERVIEW', icon: LayoutDashboard},
  {id: 'accounts', label: 'MAA 账号', en: 'ACCOUNTS', icon: UsersRound},
  {id: 'plans', label: '任务计划', en: 'TASK PLANS', icon: ListTodo},
  {id: 'inventory', label: '库存保持', en: 'INVENTORY', icon: Package},
  {id: 'infrastructure', label: '基建排班', en: 'INFRASTRUCTURE', icon: Building2},
  {id: 'orundum', label: '搓玉策略', en: 'ORUNDUM', icon: Gem},
  {id: 'logs', label: '运行日志', en: 'ACTIVITY LOG', icon: ScrollText},
  {id: 'settings', label: '系统设置', en: 'SETTINGS', icon: Settings2},
] as const
const page = ref<Page>('overview')
const currentNav = computed(() => nav.find(n => n.id === page.value)!)
const demo = ref(new URLSearchParams(location.search).get('demo') === '1')
const data = ref<Overview>(demo.value ? makeDemo() : {accounts: [], agents: [], jobs: [], events: [], server_time: '', mode: 'read_only', version: '0.1.0'})
const loggedIn = ref(false), checking = ref(true), busy = ref(false), connected = ref(false), mobileNav = ref(false)
const username = ref('admin'), password = ref(''), loginError = ref(''), toast = ref(''), fetchError = ref('')
const date = ref(new Date()), theme = ref(document.documentElement.dataset.theme || 'light')
const accountFilter = ref('all'), activeAccountID = ref(''), search = ref(''), sortGap = ref(false), logFilter = ref('all')
const drawer = ref<Account | null>(null), drawerTab = ref<'overview' | 'policy' | 'binding'>('overview'), shift = ref(0)
const taskModal = ref(false), taskAccount = ref(''), taskType = ref('日常任务'), help = ref(false)
const formPolicy = ref<Policy>({medicine_budget: null, stone_budget: null, expiring_hours: null, verified: false, source: ''})
const preview = ref<{valid: boolean; errors: string[]; original: Policy; proposed: Policy; message: string} | null>(null)
const selectedBinding = ref('')
let refreshTimer: ReturnType<typeof setInterval>, clockTimer: ReturnType<typeof setInterval>, toastTimer: ReturnType<typeof setTimeout>
const count = (n: number) => String(n).padStart(2, '0')
const time = (s: string) => s ? new Date(s).toLocaleTimeString('zh-CN', {hour: '2-digit', minute: '2-digit', second: '2-digit', timeZone: 'Asia/Shanghai'}) : '尚无记录'
const dateLabel = computed(() => date.value.toLocaleDateString('zh-CN', {year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'long', timeZone: 'Asia/Shanghai'}))
const onlineAccounts = computed(() => data.value.accounts.filter(a => a.agent_online))
const running = computed(() => data.value.accounts.filter(a => a.status === 'running').length)
const pending = computed(() => data.value.jobs.filter(j => ['pending', 'dispatched'].includes(j.state)).length)
const onlineAgent = computed(() => data.value.agents.some(a => a.online))
const maaRunning = computed(() => data.value.accounts.some(a => a.instance?.process_running))
const deviceConnected = computed(() => data.value.accounts.some(a => a.instance?.device_connected === true))
const filteredAccounts = computed(() => data.value.accounts.filter(a => accountFilter.value === 'all' || a.status === accountFilter.value))
const activeAccount = computed(() => data.value.accounts.find(a => a.id === activeAccountID.value) || data.value.accounts[0])
const inventory = computed(() => {
  let rows = [...(activeAccount.value?.profile?.inventory || [])].filter(i => `${i.name} ${i.id} ${i.stage}`.toLowerCase().includes(search.value.toLowerCase()))
  if (sortGap.value) rows.sort((a, b) => (b.target == null || b.current == null ? -1 : b.target - b.current) - (a.target == null || a.current == null ? -1 : a.target - a.current))
  return rows
})
const schedule = computed(() => activeAccount.value?.profile?.schedule)
const currentShift = computed(() => schedule.value?.plans[shift.value] || schedule.value?.plans[0])
const roomNames: Record<string, string> = {control: '控制中枢', manufacture: '制造站', trading: '贸易站', power: '发电站', meeting: '会客室', hire: '办公室', dormitory: '宿舍', processing: '加工站', training: '训练室', recycle: '回收站'}
const taskNames: Record<string, string> = {StartUp:'开始唤醒', DepotMaintain:'库存保持', Infrast:'基建换班', Recruit:'公开招募', Mall:'信用收支', Award:'领取奖励', UserDataUpdate:'更新数据', Fight:'理智作战'}
const events = computed(() => data.value.events.filter(e => logFilter.value === 'all' || e.level === logFilter.value).filter(e => `${e.message} ${e.account_id}`.toLowerCase().includes(search.value.toLowerCase())))
const bindings = computed(() => data.value.agents.flatMap((agent: Agent) => (agent.instance?.profiles || []).map(p => ({key: `${agent.agent_id}|${agent.instance!.id}|${p.id}`, label: `${agent.hostname} / ${p.name} / ${p.account_hint || '账号待核实'}`}))))

function notify(message: string) {toast.value = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.value = '', 4200)}
function navigate(id: Page) {page.value = id; mobileNav.value = false; search.value = ''; shift.value = 0; window.scrollTo({top: 0})}
function toggleTheme() {theme.value = theme.value === 'light' ? 'dark' : 'light'; document.documentElement.dataset.theme = theme.value; try {localStorage.setItem('maacc-theme', theme.value)} catch {}}
function toggleDemo() {const u = new URL(location.href); demo.value ? u.searchParams.delete('demo') : u.searchParams.set('demo', '1'); location.assign(u)}
async function refresh(silent = false) {
 if (demo.value) {if (!silent) notify('演示数据已刷新；未连接实际设备'); return}
 busy.value = !silent
 try {data.value = await request<Overview>('/overview'); connected.value = true; fetchError.value = ''; if (!silent) notify('已获取最新状态')}
 catch (e) {connected.value = false; fetchError.value = (e as Error).message}
 finally {busy.value = false}
}
async function login() {
 busy.value = true; loginError.value = ''
 try {const r = await request<{csrf_token: string}>('/auth/login', {method: 'POST', body: JSON.stringify({username: username.value, password: password.value})}); setCSRF(r.csrf_token); password.value = ''; loggedIn.value = true; await refresh(true)}
 catch (e) {loginError.value = (e as Error).message} finally {busy.value = false}
}
async function logout() {if (!demo.value) {try {await request('/auth/logout', {method: 'POST'})} catch {notify('退出失败，请重试'); return}} loggedIn.value = false; setCSRF('')}
function openDetails(a: Account) {drawer.value = a; drawerTab.value = 'overview'; preview.value = null; formPolicy.value = {...a.policy}; selectedBinding.value = ''}
function newTask(a?: Account) {taskAccount.value = a?.id || data.value.accounts[0]?.id || ''; taskType.value = '日常任务'; taskModal.value = true}
function addTask() {
 if (!demo.value) return
 const a = data.value.accounts.find(a => a.id === taskAccount.value); if (!a) return
 const id = `demo-${Date.now()}`
 data.value.jobs.push({id, account_id: a.id, type: taskType.value, state: 'pending', progress: 0, created_at: new Date().toISOString()})
 data.value.events.unshift({id: Date.now(), time: new Date().toISOString(), level: 'info', account_id: a.id, message: `[演示] ${taskType.value}已加入队列`})
 taskModal.value = false; notify('演示任务已加入队列；未向实际设备下发')
}
function cancelJob(id: string) {if (!demo.value) return; const j = data.value.jobs.find(j => j.id === id); if (j) {j.state = 'cancelled'; const a = data.value.accounts.find(a => a.id === j.account_id); if (a && !data.value.jobs.some(other => other.account_id === a.id && other.state === 'running')) a.status = 'idle'} notify('演示任务已取消；未控制实际设备')}
function exportData(value: unknown, name: string) {const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], {type: 'application/json'})); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); URL.revokeObjectURL(url); notify('只读数据已导出')}
async function previewPolicy() {
 if (!drawer.value) return
 if (demo.value) {const errors = drawer.value.role === 'secondary' && (formPolicy.value.medicine_budget !== 0 || formPolicy.value.stone_budget !== 0 || formPolicy.value.expiring_hours !== 48) ? ['副账号必须保持药剂 0、源石 0、临期窗口 48 小时'] : []; preview.value = {valid: !errors.length, errors, original: drawer.value.policy, proposed: {...formPolicy.value}, message: '演示差异预览 / 不保存或应用'}; return}
 try {preview.value = await request(`/accounts/${drawer.value.id}/policies/preview`, {method: 'POST', body: JSON.stringify(formPolicy.value)})} catch (e) {notify((e as Error).message)}
}
async function bindAccount() {
 if (!drawer.value || !selectedBinding.value) return
 if (demo.value) {notify('演示模式不更改实际绑定'); return}
 const [agent_id, instance_id, profile_id] = selectedBinding.value.split('|')
 try {await request(`/accounts/${drawer.value.id}/binding`, {method: 'POST', body: JSON.stringify({agent_id, instance_id, profile_id})}); await refresh(true); drawer.value = data.value.accounts.find(a => a.id === drawer.value!.id) || null; notify('只读账号绑定已保存；原 MAA 配置保持不变')} catch (e) {notify((e as Error).message)}
}
let previousFocus: HTMLElement | null = null
watch(() => !!drawer.value || taskModal.value || help.value, async open => {
 if (open) previousFocus = document.activeElement as HTMLElement
 document.body.style.overflow = open ? 'hidden' : ''
 await nextTick()
 if (open) document.querySelector<HTMLElement>('[role="dialog"] button')?.focus()
 else previousFocus?.focus()
})
function closeOverlays(e: KeyboardEvent) {
 if (e.key === 'Escape') {drawer.value = null; taskModal.value = false; help.value = false; mobileNav.value = false}
 if (e.key === 'Tab' && (drawer.value || taskModal.value || help.value)) {
  const nodes = Array.from(document.querySelectorAll<HTMLElement>('[role="dialog"] button:not(:disabled), [role="dialog"] input, [role="dialog"] select, [role="dialog"] a[href]')).filter(n => n.offsetParent !== null)
  const first = nodes[0], last = nodes[nodes.length - 1]
  if (e.shiftKey && document.activeElement === first) {e.preventDefault(); last?.focus()}
  else if (!e.shiftKey && document.activeElement === last) {e.preventDefault(); first?.focus()}
 }
}
onMounted(async () => {
 if (demo.value) {loggedIn.value = true; connected.value = true} else {try {const r = await request<{csrf_token: string}>('/auth/session'); setCSRF(r.csrf_token); loggedIn.value = true; await refresh(true)} catch {}}
 checking.value = false; refreshTimer = setInterval(() => {if (loggedIn.value) refresh(true)}, 25000); clockTimer = setInterval(() => date.value = new Date(), 1000); document.addEventListener('keydown', closeOverlays)
})
onUnmounted(() => {clearInterval(refreshTimer); clearInterval(clockTimer); clearTimeout(toastTimer); document.removeEventListener('keydown', closeOverlays)})
</script>

<template>
 <div class="startup" v-if="checking"><span class="brand-mark">M<span></span></span><p>正在连接管理中心…</p></div>
 <div v-else-if="!loggedIn" class="login-layout">
  <div class="login-story"><a class="brand" href="/"><span class="brand-mark">M<span></span></span><div><strong>MAA</strong><small>CONTROL CENTER</small></div></a><div class="login-title"><span class="eyebrow">// YOUR DAILY OPERATIONS</span><h1>让日常，<br>有条不紊。</h1><p>看见每个账号的运行状态，<br>让现有的挂机安排继续安心运转。</p></div><SystemGraph :agent-online="false" :maa-running="false" :connected="false" :demo="false"/><span class="login-foot">SELF-HOSTED / OPEN SOURCE / V0.1.0</span></div>
  <main class="login-panel"><button class="icon-button login-theme" aria-label="切换深浅主题" @click="toggleTheme"><Moon v-if="theme === 'light'" :size="20"/><Sun v-else :size="20"/></button><div class="login-form-wrap"><span class="eyebrow">// ADMIN ACCESS</span><h2>登录控制中心</h2><p class="muted">所有账号与设备，由你掌控。</p><form @submit.prevent="login"><label>管理员账号<input v-model="username" name="username" autocomplete="username" required/></label><label>登录密码<input v-model="password" type="password" name="password" autocomplete="current-password" required placeholder="输入管理员密码"/></label><p class="inline-alert" role="alert" v-if="loginError">{{ loginError }}</p><button class="button primary" type="submit" :disabled="busy">{{ busy ? '正在登录…' : '进入管理中心' }}<ArrowRight :size="18"/></button></form><div class="login-security"><LockKeyhole :size="14"/>独立部署 / 账号数据保存在自己的设备</div><button class="text-button" @click="toggleDemo">先看看交互演示<ArrowUpRight :size="15"/></button></div></main>
 </div>
 <div v-else class="app-shell" :inert="!!drawer || taskModal || help">
  <a class="skip-link" href="#main">跳转到主要内容</a>
  <aside class="sidebar" :class="{open: mobileNav}">
   <a class="brand" href="#" @click.prevent="navigate('overview')"><span class="brand-mark">M<span></span></span><div><strong>MAA</strong><small>CONTROL CENTER</small></div></a>
   <div class="workspace-label"><span class="tiny-square"></span>PERSONAL WORKSPACE<small>自托管控制中心</small></div>
   <nav aria-label="主导航"><button v-for="(item, n) in nav" :key="item.id" :class="{selected: page === item.id}" :aria-current="page === item.id ? 'page' : undefined" @click="navigate(item.id)"><component :is="item.icon" :size="18" :stroke-width="1.65"/><span>{{ item.label }}<small>{{ item.en }}</small></span><b>{{ String(n + 1).padStart(2, '0') }}</b></button></nav>
   <div class="sidebar-bottom"><div class="read-only-note"><ShieldCheck :size="18"/><strong>{{ demo ? '交互演示' : '只读保护已启用' }}</strong><small>{{ demo ? '所有操作仅在当前页面模拟' : '保留原有 MAA 配置与排班' }}</small></div><a href="https://github.com/yumi233/maa-control-center" target="_blank" rel="noopener noreferrer">开源项目 <span>V{{ data.version }}</span><ArrowUpRight :size="14"/></a><button class="profile-button" @click="logout"><span class="admin-avatar">A</span><span>Administrator<small>系统管理员</small></span><LogOut :size="16"/></button></div>
  </aside>
  <button v-if="mobileNav" class="mobile-scrim" aria-label="关闭导航" @click="mobileNav = false"></button>
  <div class="main-shell">
   <header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" aria-label="打开导航" @click="mobileNav = !mobileNav"><Menu :size="21"/></button><span>工作空间</span><ChevronRight :size="13"/><strong>{{ currentNav.label }}</strong></div><div class="topbar-actions"><span class="server-badge"><i></i>{{ demo ? '演示环境' : connected ? '服务已连接' : '服务连接中断' }}</span><button class="icon-button" aria-label="使用帮助" @click="help = true"><CircleHelp :size="18"/></button><button class="icon-button" aria-label="切换深浅主题" @click="toggleTheme"><Moon v-if="theme === 'light'" :size="18"/><Sun v-else :size="18"/></button><span class="top-avatar">A</span></div></header>
   <main id="main" class="main-content">
    <div v-if="demo" class="demo-banner"><span><AlertTriangle :size="15"/><strong>演示模式</strong><span>以下为模拟数据，所有操作均不会影响实际设备。</span></span><button @click="toggleDemo">返回真实环境<ArrowRight :size="14"/></button></div>
    <div v-if="fetchError" class="connection-alert" role="alert"><WifiOff :size="17"/>{{ fetchError }}。保留的状态可能已过期。<button class="text-button" @click="refresh()">重新连接</button></div>
    <section class="page-heading"><div><span class="eyebrow">// {{ page === 'overview' ? 'OPERATIONS OVERVIEW' : currentNav.en }}</span><h1>{{ page === 'overview' ? '全局总览' : currentNav.label }}<span class="heading-tag">{{ demo ? 'DEMO' : 'READ ONLY' }}</span></h1><p>{{ page === 'overview' ? '日常尽在掌握，让每一份理智都有去处。' : page === 'accounts' ? '每个账号，保留自己的运行方式。' : page === 'inventory' ? '按实际缺口规划补货，原有目标清晰可见。' : page === 'infrastructure' ? '独立读取每个账号的班次与干员安排。' : page === 'plans' ? '查看已有任务顺序，明确调度归属。' : page === 'orundum' ? '先核实资源与能力，再决定是否切换。' : page === 'logs' ? '从每一条记录，了解任务的来龙去脉。' : '管理中心的连接、权限与接入状态。' }}</p></div><div class="heading-actions"><span class="current-date">{{ dateLabel }}</span><div><button class="button" @click="refresh()" :disabled="busy"><RefreshCw :size="15" :class="{spinning: busy}"/>刷新状态</button><button v-if="page === 'overview' || page === 'plans'" class="button primary" :disabled="!demo" :title="demo ? '添加演示任务' : '只读模式下无法下发任务'" @click="newTask()"><Plus :size="17"/>新建任务</button><button v-else-if="page === 'accounts'" class="button primary" @click="openDetails(data.accounts[0]!)" :disabled="!data.accounts.length"><Link2 :size="16"/>管理绑定</button></div></div></section>

    <template v-if="page === 'overview'">
     <section class="overview-board"><div class="stats-area"><div class="stats-title"><span class="eyebrow">// TODAY'S STATUS</span><span class="muted">{{ demo ? '模拟运行数据' : '以最近一次上报为准' }}</span></div><div class="stats-numbers"><div class="stat-main"><span class="stat-label">管理账号<span>ACCOUNTS</span></span><strong>{{ count(data.accounts.length) }}<small>/ TOTAL</small></strong><span class="stat-caption">{{ data.accounts.filter(a => a.bound).length }} 个已绑定配置</span></div><div class="stat"><span class="stat-label">运行中<span>RUNNING</span></span><strong>{{ count(running) }}</strong><span class="stat-caption"><i class="tiny-square"></i>{{ running ? '任务正在执行' : '尚无已确认的运行任务' }}</span></div><div class="stat"><span class="stat-label">等待执行<span>QUEUED</span></span><strong>{{ count(pending) }}</strong><span class="stat-caption">{{ demo ? '按资源锁顺序执行' : '沿用现有 MAA 调度' }}</span></div></div></div><SystemGraph :agent-online="onlineAgent" :maa-running="maaRunning" :connected="deviceConnected" :demo="demo"/></section>
     <div class="dashboard-grid"><div class="dashboard-left"><section class="accounts-section"><div class="section-heading"><div><span class="section-index">01</span><h2>账号监控<small>ACCOUNTS</small></h2><span class="section-count">{{ count(data.accounts.length) }}</span></div><button class="text-button" @click="navigate('accounts')">管理账号<ArrowUpRight :size="16"/></button></div><div class="account-grid"><AccountCard v-for="(a, index) in data.accounts" :key="a.id" :account="a" :index="index" :job="data.jobs.find(j => j.account_id === a.id && j.state === 'running')" :demo="demo" @detail="openDetails" @run="newTask"/></div></section>
      <section class="activity-section"><div class="section-heading"><div><span class="section-index">02</span><h2>最近动态<small>RECENT ACTIVITY</small></h2></div><button class="text-button" @click="navigate('logs')">全部日志<ArrowUpRight :size="16"/></button></div><div class="activity-table" v-if="data.events.length"><div v-for="e in data.events.slice(0, 4)" :key="e.id" class="activity-row"><span class="activity-time">{{ time(e.time) }}</span><span class="activity-level">{{ e.level === 'info' ? '记录' : '注意' }}</span><p>{{ e.message }}</p><ChevronRight :size="15"/></div></div><div v-else class="quiet-empty"><ScrollText :size="24"/><p>设备接入后，这里会记录连接变化与任务动态。</p></div></section>
     </div><aside class="dashboard-right"><section class="queue-panel"><div class="section-heading"><div><span class="tiny-square"></span><h2>任务队列</h2></div><span class="mono">{{ count(data.jobs.filter(j => j.state !== 'cancelled').length) }}</span></div><div v-if="data.jobs.some(j => j.state !== 'cancelled')" class="queue-list"><div class="queue-item" v-for="(j, i) in data.jobs.filter(j => j.state !== 'cancelled')" :key="j.id"><div class="queue-number">{{ String(i + 1).padStart(2, '0') }}</div><div><strong>{{ j.type }}</strong><small>{{ data.accounts.find(a => a.id === j.account_id)?.name }}<span>/</span>{{ j.state === 'running' ? '执行中' : '等待执行' }}</small></div><button class="icon-button" aria-label="取消演示任务" @click="cancelJob(j.id)"><Pause :size="15"/></button><div v-if="j.state === 'running'" class="queue-progress"><span :style="{width: j.progress + '%'}"></span></div></div></div><div v-else class="queue-empty"><ListTodo :size="32" :stroke-width="1"/><strong>当前没有排队任务</strong><p>新的任务会按账号与设备顺序<br>出现在这里。</p></div><button class="queue-all text-button" @click="navigate('plans')">查看任务计划<ArrowRight :size="15"/></button></section>
      <section class="resource-panel"><span class="eyebrow">// RESOURCE GUARD</span><h2>每一份资源，<br>都有边界。</h2><ShieldCheck class="guard-icon" :size="72" :stroke-width="0.8"/><div class="guard-row"><Check :size="14"/>副账号禁用普通理智药</div><div class="guard-row"><Check :size="14"/>副账号禁用源石恢复</div><div class="guard-row"><Clock3 :size="14"/>优先使用 48h 内临期药</div><p>{{ data.accounts.find(a => a.role === 'secondary')?.policy.verified ? '已读取现有配置；控制功能仍受接入校验约束。' : '以上为策略要求，接入后核对实际配置。' }}</p><button class="text-button" @click="data.accounts[1] && openDetails(data.accounts[1])">查看资源策略<ArrowUpRight :size="15"/></button></section>
     </aside></div>
     <div class="bottom-status"><span><i class="tiny-square"></i>{{ demo ? 'DEMO DATA' : 'READ-ONLY CONNECTION' }}</span><span>上次同步 {{ time(data.server_time) }}<span class="separator">/</span>每 25 秒自动刷新</span><span class="bottom-status-right">{{ onlineAccounts.length }} / {{ data.accounts.length }} 账号的 Agent 在线</span></div>
    </template>

    <template v-else-if="page === 'accounts'"><div class="filter-toolbar"><div class="filter-tabs"><button :class="{active: accountFilter === 'all'}" @click="accountFilter = 'all'">全部账号 <b>{{ data.accounts.length }}</b></button><button :class="{active: accountFilter === 'running'}" @click="accountFilter = 'running'">运行中 <b>{{ running }}</b></button><button :class="{active: accountFilter === 'offline'}" @click="accountFilter = 'offline'">已离线 <b>{{ data.accounts.filter(a => a.status === 'offline').length }}</b></button></div><span class="muted">账号与 MAA 实例分别管理</span></div><div class="account-grid all-accounts"><AccountCard v-for="(a, index) in filteredAccounts" :key="a.id" :account="a" :index="index" :demo="demo" :job="data.jobs.find(j => j.account_id === a.id && j.state === 'running')" @detail="openDetails" @run="newTask"/></div><div v-if="!filteredAccounts.length" class="empty-large"><UsersRound :size="36"/><h2>没有符合筛选条件的账号</h2><p>切换筛选查看其他状态的账号。</p></div><div class="info-strip"><ShieldCheck :size="18"/>同一 MAA 下的不同配置档分别读取，账号之间不会互相覆盖。</div></template>

    <template v-else-if="page === 'inventory'"><div class="filter-toolbar"><div class="filter-tabs"><button v-for="a in data.accounts" :key="a.id" :class="{active: activeAccount?.id === a.id}" @click="activeAccountID = a.id">{{ a.name }}</button></div><button class="button small" @click="exportData(inventory, 'inventory-readonly.json')"><Download :size="14"/>导出计划</button></div><div class="info-strip"><Package :size="17"/>{{ demo ? '演示库存 / 所有数量均为模拟数据' : '目标读取自现有计划；当前库存未验证账号归属时留空，不计算虚假达成率。' }}</div><div class="table-toolbar"><label class="search-input"><Search :size="16"/><input v-model="search" placeholder="搜索材料 ID、名称或关卡" aria-label="搜索库存"/></label><button class="button small" :class="{selected: sortGap}" @click="sortGap = !sortGap"><ArrowDownWideNarrow :size="15"/>{{ sortGap ? '按缺口排序' : '按原计划排序' }}</button><span class="muted">{{ inventory.length }} 项材料</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>材料 / MATERIAL</th><th>当前库存</th><th>最低库存</th><th>目标库存</th><th>建议上限</th><th>达成率</th><th>关卡</th><th>优先级</th></tr></thead><tbody><tr v-for="(item, i) in inventory" :key="`${item.id}-${i}`"><td><span class="material-glyph" aria-hidden="true">{{ i + 1 }}</span><strong>{{ item.name }}</strong><small class="material-id">{{ item.id }}</small></td><td class="numeric">{{ item.current ?? '—' }}</td><td class="numeric">{{ item.minimum ?? '—' }}</td><td class="numeric"><strong>{{ item.target?.toLocaleString() ?? '—' }}</strong></td><td class="numeric">{{ item.upper ?? '—' }}</td><td><div v-if="item.current != null && item.target" class="inventory-progress"><span><i :style="{width: Math.min(100, item.current / item.target * 100) + '%'}"></i></span><small>{{ Math.min(100, Math.round(item.current / item.target * 100)) }}%</small></div><span v-else class="muted">待识别</span></td><td class="mono">{{ item.stage }}</td><td class="mono">{{ count(item.priority) }}</td></tr></tbody></table></div><div v-if="!inventory.length" class="empty-large"><Package :size="38"/><h2>等待导入现有库存计划</h2><p>绑定配置后，这里将展示材料、原有目标和关卡。</p></div><p class="table-note">“—” 表示尚无已验证数据。最低库存与建议上限属于 Web 规划字段，未设置时不填入默认值。</p></template>

    <template v-else-if="page === 'infrastructure'"><div class="filter-toolbar"><div class="filter-tabs"><button v-for="a in data.accounts" :key="a.id" :class="{active: activeAccount?.id === a.id}" @click="activeAccountID = a.id; shift = 0">{{ a.name }}</button></div><button class="button small" @click="exportData(schedule, 'infrastructure-readonly.json')" :disabled="!schedule"><Download :size="14"/>导出排班</button></div><div class="info-strip"><LockKeyhole :size="17"/>原有排班只读展示，所有干员、产物与扩展字段完整保留。</div><div v-if="schedule" class="schedule-content"><div class="schedule-title"><div><span class="eyebrow">// EXISTING SCHEDULE</span><h2>{{ schedule.title || '现有基建排班' }}</h2></div><span class="status-pill"><LockKeyhole :size="13"/>只读</span></div><div class="shift-tabs"><button v-for="(p, i) in schedule.plans" :key="i" :class="{active: shift === i}" @click="shift = i"><span>{{ count(i + 1) }}</span><strong>{{ p.name || `班次 ${i + 1}` }}</strong><small>{{ p.period?.map(t => t.join(' — ')).join(' / ') || '按 MAA 配置轮换' }}</small></button></div><div class="rooms-grid"><article v-for="(rooms, roomType) in currentShift?.rooms" :key="roomType" class="room-panel"><div class="room-title"><Building2 :size="18"/><h3>{{ roomNames[roomType] || roomType }}</h3><span class="mono">{{ rooms.length }}</span></div><div v-for="(room, i) in rooms" :key="i" class="room-detail"><span class="room-number">{{ count(i + 1) }}</span><div><strong>{{ room.skip ? '保持原样 / 跳过换班' : room.operators?.join(' / ') || room.group || '沿用 MAA 选人规则' }}</strong><small>制造产物：{{ room.product || '沿用现有设置' }}</small></div></div></article></div><p class="table-note">产物字段仅表示已保存的配置，不代表具备经过验证的自动配方切换能力。</p></div><div v-else class="empty-large"><Building2 :size="40"/><h2>等待接入现有基建文件</h2><p>Agent 只读取允许目录内的配置，原文件保持不变。</p></div></template>

    <template v-else-if="page === 'plans'"><div class="info-strip"><Clock3 :size="17"/>当前调度归属：现有 MAA。Web 自动调度保持关闭，避免重复执行。</div><div class="plans-layout"><article v-for="(a, i) in data.accounts" :key="a.id" class="plan-panel"><div class="section-heading"><div><span class="section-index">{{ count(i + 1) }}</span><h2>{{ a.name }}</h2></div><StatusPill :status="a.status"/></div><ol class="task-sequence"><li v-for="(task, j) in a.profile?.tasks || []" :key="j"><span class="task-step">{{ count(j + 1) }}</span><div><strong>{{ taskNames[task] || task }}</strong><small>沿用账号现有配置</small></div><CheckCheck :size="17"/></li></ol><div v-if="!a.profile?.tasks.length" class="quiet-empty"><ListTodo :size="28"/><p>接入后将展示现有任务顺序。</p></div><button class="button wide" :disabled="!demo" @click="newTask(a)"><Plus :size="16"/>添加演示任务</button></article></div><section class="activity-section" v-if="data.jobs.length"><div class="section-heading"><h2>本次演示任务</h2><span class="muted">仅保存在当前页面</span></div><div v-for="j in data.jobs" :key="j.id" class="activity-row"><span class="activity-level">{{ j.state === 'cancelled' ? '已取消' : j.state === 'running' ? '运行中' : '待执行' }}</span><p>{{ j.type }}</p><span>{{ data.accounts.find(a => a.id === j.account_id)?.name }}</span><button class="text-button" :disabled="j.state === 'cancelled'" @click="cancelJob(j.id)">取消</button></div></section></template>

    <template v-else-if="page === 'orundum'"><div class="orundum-intro"><Gem :size="76" :stroke-width="1"/><div><span class="eyebrow">// SAFETY BEFORE AUTOMATION</span><h2>条件尚未齐备，暂不自动切换。</h2><p>现有基建排班继续保持。完成库存、资源预留和能力验证后，再开放切换。</p></div><span class="status-pill"><LockKeyhole :size="14"/>当前禁用</span></div><div class="checks-list"><div v-for="(item, i) in ['普通库存保持目标已经满足', '活动优先策略已核实', '搓玉所需材料与龙门币预留已核实', '干员排班与现有生产分工兼容', '自动配方切换经过真实环境验证', '可以可靠恢复原始生产模式']" :key="item"><span class="section-index">{{ count(i + 1) }}</span><strong>{{ item }}</strong><span class="status-pill unknown"><i></i>待验证</span></div></div><div class="info-strip"><ShieldCheck :size="18"/>所有检查通过前，API 与页面均不允许开启自动搓玉。</div></template>

    <template v-else-if="page === 'logs'"><div class="table-toolbar"><div class="filter-tabs"><button :class="{active: logFilter === 'all'}" @click="logFilter = 'all'">全部记录</button><button :class="{active: logFilter === 'info'}" @click="logFilter = 'info'">常规记录</button><button :class="{active: logFilter === 'warning'}" @click="logFilter = 'warning'">需要注意</button></div><label class="search-input"><Search :size="16"/><input v-model="search" placeholder="搜索日志内容" aria-label="搜索日志"/></label><button class="button small" @click="exportData(events, 'events.json')"><Download :size="14"/>导出</button></div><div class="log-events"><div v-for="e in events" :key="e.id" class="log-event"><span class="mono">{{ time(e.time) }}</span><span class="activity-level">{{ e.level === 'info' ? 'INFO' : 'NOTICE' }}</span><p>{{ e.message }}</p></div><div v-if="!events.length" class="quiet-empty"><ScrollText :size="30"/><p>没有符合条件的记录。</p></div></div><div class="section-heading log-subheading"><h2>MAA 实例日志</h2><span class="muted">最近 60 行 / 已过滤敏感字段</span></div><div class="filter-tabs"><button v-for="a in data.accounts" :key="a.id" :class="{active: activeAccount?.id === a.id}" @click="activeAccountID = a.id">{{ a.name }}</button></div><div class="log-console"><p v-for="(line, i) in activeAccount?.instance?.logs || []" :key="i"><span>{{ count(i + 1) }}</span>{{ line }}</p><p v-if="!activeAccount?.instance?.logs.length">连接 Agent 后，这里将显示 MAA 的只读日志。同一实例的日志不自动归属到某个账号。</p></div></template>

    <template v-else-if="page === 'settings'"><div class="settings-grid"><section class="settings-panel"><div class="section-heading"><h2>控制中心</h2><span class="eyebrow">SYSTEM</span></div><div class="setting-row"><span>当前版本</span><strong>V{{ data.version }}</strong></div><div class="setting-row"><span>数据库</span><strong>{{ demo ? '演示 / 内存' : 'SQLite / WAL' }}</strong></div><div class="setting-row"><span>运行模式</span><span class="status-pill">{{ demo ? '交互演示' : '只读接入' }}</span></div><div class="setting-row"><span>自动调度</span><strong>未开启</strong></div><div class="setting-row"><span>Windows 配置同步</span><strong>未开启</strong></div><div class="setting-row"><span>外观</span><button class="button small" @click="toggleTheme">{{ theme === 'light' ? '切换深色' : '切换浅色' }}</button></div></section><section class="settings-panel"><div class="section-heading"><h2>设备连接</h2><Monitor :size="18"/></div><div class="agent-setting" v-for="a in data.agents" :key="`${a.agent_id}-${a.instance?.id}`"><Monitor :size="24"/><div><strong>{{ a.hostname }}</strong><small>{{ a.os }} / AGENT {{ a.version }}</small><small>最近心跳 {{ time(a.last_seen) }}</small></div><span class="status-pill" :class="{offline: !a.online}"><i></i>{{ a.online ? '在线' : '离线' }}</span></div><div v-if="!data.agents.length" class="quiet-empty"><Monitor :size="30"/><p>尚无已配对的 Windows Agent。</p></div><p class="table-note">Agent 使用独立令牌与 HTTPS 上报。配对令牌不会显示在页面中。</p></section><section class="settings-panel"><div class="section-heading"><h2>接入保护</h2><ShieldCheck :size="18"/></div><div class="setting-row"><span>原有 MAA 配置</span><strong>只读</strong></div><div class="setting-row"><span>账号与实例绑定</span><strong>管理员确认</strong></div><div class="setting-row"><span>控制指令</span><strong>默认拒绝</strong></div><div class="setting-row"><span>搓玉自动切换</span><strong>等待真实验证</strong></div><button class="button wide" @click="help = true">查看接入说明<ArrowUpRight :size="15"/></button></section><section class="settings-panel demo-setting"><span class="eyebrow">// TRY THE WORKFLOW</span><h2>{{ demo ? '回到实际运行环境' : '体验完整交互' }}</h2><p>演示模式可以体验任务添加、库存筛选和策略预览，模拟数据有明确标记。</p><button class="button primary" @click="toggleDemo">{{ demo ? '退出演示模式' : '打开交互演示' }}<ArrowRight :size="16"/></button></section></div></template>
   </main>
   <footer class="app-footer"><span>MAA CONTROL CENTER<span class="separator">/</span>让日常，有条不紊。</span><button class="text-button" @click="toggleDemo">{{ demo ? '退出演示' : '交互演示' }}<ArrowUpRight :size="13"/></button><span>SELF-HOSTED / V{{ data.version }}</span></footer>
  </div>
 </div>

 <div v-if="drawer" class="overlay" @click.self="drawer = null"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-header"><div><span class="eyebrow">// ACCOUNT DETAILS</span><h2 id="drawer-title">{{ drawer.name }}</h2></div><button class="icon-button" aria-label="关闭详情" @click="drawer = null"><X :size="21"/></button></div><div class="drawer-tabs filter-tabs"><button :class="{active: drawerTab === 'overview'}" @click="drawerTab = 'overview'">配置概览</button><button :class="{active: drawerTab === 'policy'}" @click="drawerTab = 'policy'">策略预览</button><button :class="{active: drawerTab === 'binding'}" @click="drawerTab = 'binding'">实例绑定</button></div><div class="drawer-body" v-if="drawerTab === 'overview'"><StatusPill :status="drawer.status"/><div class="setting-row"><span>配置档</span><strong>{{ drawer.profile?.name || '未绑定' }}</strong></div><div class="setting-row"><span>启动账号标识</span><strong>{{ drawer.profile?.account_hint || '待确认' }}</strong></div><div class="setting-row"><span>MAA 版本</span><strong>{{ drawer.instance?.version || '待确认' }}</strong></div><div class="setting-row"><span>普通理智药预算</span><strong>{{ drawer.policy.medicine_budget ?? '待核实' }}</strong></div><div class="setting-row"><span>源石恢复预算</span><strong>{{ drawer.policy.stone_budget ?? '待核实' }}</strong></div><div class="setting-row"><span>临期药窗口</span><strong>{{ drawer.policy.expiring_hours == null ? '待核实' : drawer.policy.expiring_hours ? `${drawer.policy.expiring_hours} 小时` : '未启用' }}</strong></div><div class="info-strip"><LockKeyhole :size="16"/>上述为实际读取值，不会自动覆盖现有配置。</div><h3 class="subheading">现有任务顺序</h3><ol class="drawer-task-list"><li v-for="t in drawer.profile?.tasks || []" :key="t">{{ taskNames[t] || t }}</li></ol><div class="fingerprint" v-if="drawer.instance?.fingerprint"><span>配置 SHA-256</span><code>{{ drawer.instance.fingerprint }}</code></div></div><form v-else-if="drawerTab === 'policy'" class="drawer-body" @submit.prevent="previewPolicy"><div class="info-strip">修改仅用于差异预览，当前不应用到 MAA。</div><label>普通理智药预算<input type="number" min="0" max="10000" v-model.number="formPolicy.medicine_budget" required/></label><label>源石恢复预算<input type="number" min="0" max="10000" v-model.number="formPolicy.stone_budget" required/></label><label>临期药窗口（小时）<select v-model.number="formPolicy.expiring_hours"><option :value="0">不启用</option><option :value="48">48 小时</option></select></label><button class="button primary wide" type="submit">预览修改差异<ArrowRight :size="16"/></button><div v-if="preview" class="preview-result" aria-live="polite"><h3>{{ preview.valid ? '预览校验通过' : '未通过资源约束校验' }}</h3><p v-for="e in preview.errors" :key="e">{{ e }}</p><div class="diff-row"><span>字段</span><span>原配置</span><span>预览配置</span></div><div class="diff-row" v-for="field in (['medicine_budget', 'stone_budget', 'expiring_hours'] as const)" :key="field"><span>{{ {medicine_budget: '普通药剂', stone_budget: '源石', expiring_hours: '临期窗口'}[field] }}</span><span>{{ preview.original[field] ?? '未知' }}</span><strong>{{ preview.proposed[field] ?? '未知' }}</strong></div><p class="muted">{{ preview.message }}</p></div></form><form v-else class="drawer-body" @submit.prevent="bindAccount"><p>选择 Agent 实际发现的配置档。绑定只影响控制中心的只读展示。</p><label>MAA 实例 / 配置档<select v-model="selectedBinding" required><option value="" disabled>选择已发现的配置</option><option v-for="b in bindings" :key="b.key" :value="b.key">{{ b.label }}</option></select></label><div class="info-strip"><ShieldCheck :size="17"/>请核对启动账号标识。多个配置档可以属于同一 MAA 实例。</div><button class="button primary wide" type="submit" :disabled="!selectedBinding">保存只读绑定<ArrowRight :size="16"/></button></form></section></div>
 <div v-if="taskModal" class="overlay modal-overlay" @click.self="taskModal = false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="task-title"><div class="drawer-header"><div><span class="eyebrow">// NEW DEMO TASK</span><h2 id="task-title">新建演示任务</h2></div><button class="icon-button" aria-label="关闭" @click="taskModal = false"><X :size="20"/></button></div><form class="modal-body" @submit.prevent="addTask"><div class="info-strip"><AlertTriangle :size="17"/>仅在页面中模拟，不向设备下发。</div><label>执行账号<select v-model="taskAccount" required><option v-for="a in data.accounts" :key="a.id" :value="a.id">{{ a.name }}</option></select></label><label>任务类型<select v-model="taskType"><option>日常任务</option><option>基建换班</option><option>公开招募</option><option>库存保持</option></select></label><div class="modal-actions"><button class="button" type="button" @click="taskModal = false">取消</button><button class="button primary" type="submit">加入演示队列<ArrowRight :size="16"/></button></div></form></section></div>
 <div v-if="help" class="overlay modal-overlay" @click.self="help = false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="help-title"><div class="drawer-header"><div><span class="eyebrow">// GET CONNECTED</span><h2 id="help-title">连接现有 MAA</h2></div><button class="icon-button" aria-label="关闭帮助" @click="help = false"><X :size="20"/></button></div><div class="modal-body"><ol class="help-steps"><li><strong>部署控制中心</strong><p>使用独立数据目录，配置管理员密码和 HTTPS。</p></li><li><strong>运行 Windows Agent</strong><p>指定现有 MAA 目录与允许读取的排班目录，配置独立配对令牌。</p></li><li><strong>核实账号绑定</strong><p>从实际发现结果中选择配置档，对照启动账号标识确认。</p></li><li><strong>从只读开始</strong><p>先核对任务、药剂和基建排班，完成兼容性验证再考虑启用控制。</p></li></ol><a class="button primary wide" href="https://github.com/yumi233/maa-control-center#readme" target="_blank" rel="noopener noreferrer">打开部署文档<ArrowUpRight :size="16"/></a></div></section></div>
 <Transition name="toast"><div class="toast-message" v-if="toast" role="status"><Check :size="17"/>{{ toast }}<button class="icon-button" aria-label="关闭提示" @click="toast = ''"><X :size="15"/></button></div></Transition>
</template>
